/// Shared Flutter assets for mobile + TV (single source of truth).
///
/// Brand art lives in `packages/design_system/assets/branding/` and is
/// generated by `tool/branding/make_xplayer_brand.py`. To change the logo,
/// replace these files (keep the names) or regenerate them.
abstract final class AppAssets {
  static const package = 'design_system';

  /// App mark (transparent PNG — chrome / fallback).
  static const logoMark = 'assets/branding/xplayer_mark.png';

  /// Vector mark used by the splash animation (transparent).
  static const logoMarkSvg = 'assets/branding/xplayer_mark.svg';

  /// Wordmark (always LTR; transparent PNG).
  static const wordmark = 'assets/branding/xplayer_wordmark.png';

  /// Mark + wordmark horizontal lockup — LTR (mark then wordmark).
  static const logoLockup = 'assets/branding/xplayer_lockup.png';

  /// Mark + wordmark lockup — RTL (wordmark then mark, glyphs not mirrored).
  static const logoLockupRtl = 'assets/branding/xplayer_lockup_rtl.png';

  /// UI sounds.
  static const chime = 'assets/audio/chime.mp3';
  static const unlock = 'assets/audio/unlock.mp3';

  /// Asset key form for [AudioPlayer] / some loaders.
  static String packageKey(String assetPath) =>
      'packages/$package/$assetPath';
}
